// Hazard spawn timer
let spawnTimer = 0;

function update(dt) {
  if (phase !== "playing") return;
  // Player movement
  const speed = 300; // px/sec
  let vx = 0;
  if (keys.has('ArrowRight') || keys.has('d') || keys.has('D')) vx += 1;
  if (keys.has('ArrowLeft') || keys.has('a') || keys.has('A')) vx -= 1;
  player.x += vx * speed * dt;
  player.x = Math.max(player.radius, Math.min(canvas.width - player.radius, player.x));

  // Hazard spawn
  spawnTimer -= dt;
  if (spawnTimer <= 0) {
    // spawn away from player
    let angle = Math.random() * Math.PI * 2;
    let x = canvas.width / 2 + Math.cos(angle) * (SAFE_RADIUS + Math.random() * (canvas.width/2 - SAFE_RADIUS));
    let y = canvas.height / 2 + Math.sin(angle) * (SAFE_RADIUS + Math.random() * (canvas.height/2 - SAFE_RADIUS));
    hazards.push({ x, y, vx: 0, vy: 0, radius: HAZARD_RADIUS });
    spawnTimer = SPAWN_INTERVAL;
  }

  // Move hazards
  for (const h of hazards) {
    // simple downwards movement
    h.y += HAZARD_SPEED * dt;
  }
}

